citation(eu_rec_2003_361_annex_art_1_t1, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 1 (definition of enterprise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art1_t1)', verbatim - 'An enterprise is considered to be any entity engaged in an economic activity, irrespective of its legal form.']).
citation(eu_rec_2003_361_annex_art_2_1, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 2(1) (SME category: staff, turnover and balance sheet ceilings)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art2_p1)', verbatim - 'is made up of enterprises which employ fewer than 250 persons and which have an annual turnover not exceeding EUR 50 million, and/or an annual balance sheet total not exceeding EUR 43 million.']).
citation(eu_rec_2003_361_annex_art_2_2, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 2(2) (definition of small enterprise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art2_p2)', verbatim - 'a small enterprise is defined as an enterprise which employs fewer than 50 persons and whose annual turnover and/or annual balance sheet total does not exceed EUR 10 million.']).
citation(eu_rec_2003_361_annex_art_2_3, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 2(3) (definition of microenterprise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art2_p3)', verbatim - 'a microenterprise is defined as an enterprise which employs fewer than 10 persons and whose annual turnover and/or annual balance sheet total does not exceed EUR 2 million.']).
citation(eu_rec_2003_361_annex_art_3_1, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(1) (definition of autonomous enterprise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_p1)', verbatim - 'is any enterprise which is not classified as a partner enterprise within the meaning of paragraph 2 or as a linked enterprise within the meaning of paragraph 3.']).
citation(eu_rec_2003_361_annex_art_3_2, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(2) first subparagraph (definition of partner enterprises, 25 % holding)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_p2)', verbatim - 'an enterprise (upstream enterprise) holds, either solely or jointly with one or more linked enterprises within the meaning of paragraph 3, 25 % or more of the capital or voting rights of another enterprise (downstream enterprise).']).
citation(eu_rec_2003_361_annex_art_3_t3, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(2) second subparagraph (listed investors exception)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t3)', verbatim - 'However, an enterprise may be ranked as autonomous, and thus as not having any partner enterprises, even if this 25 % threshold is reached or exceeded by the following investors']).
citation(eu_rec_2003_361_annex_art_3_t4, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(2) second subparagraph, point (a) (public investment corporations, venture capital companies, business angels)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t4)', verbatim - 'provided the total investment of those business angels in the same enterprise is less than EUR 1250000']).
citation(eu_rec_2003_361_annex_art_3_t5, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(2) second subparagraph, point (b) (universities or non-profit research centres)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t5)', verbatim - 'universities or non-profit research centres']).
citation(eu_rec_2003_361_annex_art_3_t6, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(2) second subparagraph, point (c) (institutional investors)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t6)', verbatim - 'institutional investors, including regional development funds']).
citation(eu_rec_2003_361_annex_art_3_t7, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(2) second subparagraph, point (d) (autonomous local authorities)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t7)', verbatim - 'autonomous local authorities with an annual budget of less than EUR 10 million and fewer than 5000 inhabitants.']).
citation(eu_rec_2003_361_annex_art_3_3, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) first subparagraph (definition of linked enterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_p3)', verbatim - 'are enterprises which have any of the following relationships with each other:']).
citation(eu_rec_2003_361_annex_art_3_t9, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) first subparagraph, point (a) (majority of voting rights)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t9)', verbatim - 'an enterprise has a majority of the shareholders\' or members\' voting rights in another enterprise']).
citation(eu_rec_2003_361_annex_art_3_t10, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) first subparagraph, point (b) (right to appoint or remove a majority of the board)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t10)', verbatim - 'an enterprise has the right to appoint or remove a majority of the members of the administrative, management or supervisory body of another enterprise']).
citation(eu_rec_2003_361_annex_art_3_t11, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) first subparagraph, point (c) (dominant influence by contract or articles)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t11)', verbatim - 'an enterprise has the right to exercise a dominant influence over another enterprise pursuant to a contract entered into with that enterprise or to a provision in its memorandum or articles of association']).
citation(eu_rec_2003_361_annex_art_3_t12, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) first subparagraph, point (d) (control of voting rights by shareholder agreement)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t12)', verbatim - 'an enterprise, which is a shareholder in or member of another enterprise, controls alone, pursuant to an agreement with other shareholders in or members of that enterprise, a majority of shareholders\' or members\' voting rights in that enterprise.']).
citation(eu_rec_2003_361_annex_art_3_t13, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) second subparagraph (presumption of no dominant influence)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t13)', verbatim - 'There is a presumption that no dominant influence exists if the investors listed in the second subparagraph of paragraph 2 are not involving themselves directly or indirectly in the management of the enterprise in question, without prejudice to their rights as stakeholders.']).
citation(eu_rec_2003_361_annex_art_3_t14, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) third subparagraph (indirect relationships; deferred, folded into points (a) to (d))', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t14)', verbatim - 'Enterprises having any of the relationships described in the first subparagraph through one or more other enterprises, or any one of the investors mentioned in paragraph 2, are also considered to be linked.']).
citation(eu_rec_2003_361_annex_art_3_t15, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) fourth subparagraph (relationships through natural persons, same or adjacent market)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t15)', verbatim - 'Enterprises which have one or other of such relationships through a natural person or group of natural persons acting jointly are also considered linked enterprises if they engage in their activity or in part of their activity in the same relevant market or in adjacent markets.']).
citation(eu_rec_2003_361_annex_art_3_t16, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(3) fifth subparagraph (definition of adjacent market)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_t16)', verbatim - 'is considered to be the market for a product or service situated directly upstream or downstream of the relevant market.']).
citation(eu_rec_2003_361_annex_art_3_4, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 3(4) (control by public bodies)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art3_p4)', verbatim - 'Except in the cases set out in paragraph 2, second subparagraph, an enterprise cannot be considered an SME if 25 % or more of the capital or voting rights are directly or indirectly controlled, jointly or individually, by one or more public bodies.']).
citation(eu_rec_2003_361_annex_art_4_1, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 4(1) (data of the latest approved accounting period)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art4_p1)', verbatim - 'The data to apply to the headcount of staff and the financial amounts are those relating to the latest approved accounting period and calculated on an annual basis.']).
citation(eu_rec_2003_361_annex_art_4_2, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 4(2) (two consecutive accounting periods)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art4_p2)', verbatim - 'this will not result in the loss or acquisition of the status of medium-sized, small or microenterprise unless those ceilings are exceeded over two consecutive accounting periods.']).
citation(eu_rec_2003_361_annex_art_4_3, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 4(3) (newly established enterprises, bona fide estimate)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art4_p3)', verbatim - 'In the case of newly established enterprises whose accounts have not yet been approved, the data to apply is to be derived from a bona fide estimate made in the course of the financial year.']).
