citation(eu_rec_2003_361_annex_art_6_1, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 6(1) (data of an autonomous enterprise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art6_p1)', verbatim - 'In the case of an autonomous enterprise, the data, including the number of staff, are determined exclusively on the basis of the accounts of that enterprise.']).
citation(eu_rec_2003_361_annex_art_6_2, [label - 'Commission Recommendation 2003/361/EC, Annex, Art 6(2) first subparagraph (data of an enterprise with partner or linked enterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32003H0361 (unit 32003H0361#annex_art6_p2)', verbatim - 'The data, including the headcount, of an enterprise having partner enterprises or linked enterprises are determined on the basis of the accounts and other data of the enterprise']).
