citation(eu_reg_651_2014_annex_i_art_4_3, [label - 'Commission Regulation (EU) No 651/2014, Annex I, Art 4(3) (newly-established enterprises, bona fide estimate)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02014R0651-20230701 (unit 02014R0651-20230701-annex-i#annex_art4_p3)', verbatim - 'In the case of newly-established enterprises whose accounts have not yet been approved, the data to apply is to be derived from a bona fide estimate made in the course of the financial year.']).
citation(eu_reg_651_2014_annex_i_art_5, [label - 'Commission Regulation (EU) No 651/2014, Annex I, Art 5 (staff headcount in annual work units)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02014R0651-20230701 (units 02014R0651-20230701-annex-i#annex_art5 to #annex_art5_t2)', verbatim - 'The headcount corresponds to the number of annual work units (AWU)']).
citation(eu_reg_651_2014_annex_i_art_6_1, [label - 'Commission Regulation (EU) No 651/2014, Annex I, Art 6(1) (data of an autonomous enterprise)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02014R0651-20230701 (unit 02014R0651-20230701-annex-i#annex_art6_p1)', verbatim - 'In the case of an autonomous enterprise, the data, including the number of staff, are determined exclusively on the basis of the accounts of that enterprise.']).
citation(eu_reg_651_2014_annex_i_art_6_2, [label - 'Commission Regulation (EU) No 651/2014, Annex I, Art 6(2) first subparagraph (data of an enterprise with partner or linked enterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02014R0651-20230701 (unit 02014R0651-20230701-annex-i#annex_art6_p2)', verbatim - 'The data, including the headcount, of an enterprise having partner enterprises or linked enterprises are determined on the basis of the accounts and other data of the enterprise']).
citation(eu_reg_651_2014_annex_i_art_6_t1, [label - 'Commission Regulation (EU) No 651/2014, Annex I, Art 6(2) second subparagraph (proportional aggregation of partner data)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02014R0651-20230701 (unit 02014R0651-20230701-annex-i#annex_art6_t1)', verbatim - 'Aggregation is proportional to the percentage interest in the capital or voting rights (whichever is greater). In the case of cross-holdings, the greater percentage applies.']).
citation(eu_reg_651_2014_annex_i_art_6_t2, [label - 'Commission Regulation (EU) No 651/2014, Annex I, Art 6(2) third subparagraph (100 % of linked enterprise data)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02014R0651-20230701 (unit 02014R0651-20230701-annex-i#annex_art6_t2)', verbatim - 'To the data referred to in the first and second subparagraph are added 100 % of the data of any enterprise, which is linked directly or indirectly to the enterprise in question, where the data were not already included through consolidation in the accounts.']).

test(a_recorded_key_is_implemented) :-
    implements(eu_rec_2003_361_annex_art_2_3).
test(a_recorded_gber_key_is_implemented) :-
    implements(eu_reg_651_2014_annex_i_art_3_3_c).

test(a_misspelt_key_is_not_implemented, fail) :-
    implements(eu_rec_2003_361_art_2_3).
